CREATE OR REPLACE PROCEDURE sp(arg1 real, arg2 text, arg3 real, arg4 text)
LANGUAGE plpgsql
AS $$
DECLARE
    result_val integer := 0;
    status_text text := 'pending';
BEGIN
    -- First matching arg1 threshold
    IF arg1 < 0 THEN
        result_val := CAST(arg1 * -1 AS integer);
        UPDATE "chip_model"
           SET "RAM_MiB" = arg1
         WHERE "WiFi" = arg2;
    ELSIF arg1 < 10 THEN
        result_val := CAST(arg1 + 5 AS integer);
        DELETE FROM "chip_model"
         WHERE "RAM_MiB" = arg1;
    ELSIF arg1 < 20 THEN
        result_val := CAST(arg1 * 2 AS integer);
        UPDATE "screen_mode"
           SET "used_kb" = arg3 + result_val
         WHERE "Pixels" = arg4;
    ELSIF arg1 < 30 THEN
        result_val := CAST(arg1 - 8 AS integer);
        DELETE FROM "screen_mode"
         WHERE "used_kb" = arg3;
    ELSE
        result_val := CAST(arg1 / 2 AS integer);
        status_text := 'processed';
    END IF;

    -- Handset updates, in exact order
    UPDATE "phone"
       SET "Accreditation_level" = "Accreditation_level" || '_screen_match'
     WHERE "screen_mode" IN (
               SELECT CAST(sm."Graphics_mode" AS text)
                 FROM "screen_mode" sm
                WHERE sm."Pixels" = arg4
                  AND sm."used_kb" = arg3
           )
       AND "Accreditation_level" NOT LIKE '%_screen_match';

    UPDATE "phone"
       SET "Accreditation_type" = "Accreditation_type" || '_wifi_match'
     WHERE "chip_model" IN (
               SELECT cm."Model_name"
                 FROM "chip_model" cm
                WHERE cm."WiFi" = arg2
           )
       AND "Accreditation_type" NOT LIKE '%_wifi_match';

    UPDATE "phone"
       SET "Hardware_Model_name" = "Hardware_Model_name" || '_ram_wifi_match'
     WHERE "chip_model" IN (
               SELECT cm."Model_name"
                 FROM "chip_model" cm
                WHERE cm."RAM_MiB" = arg1
                  AND cm."WiFi" = arg2
           )
       AND "Hardware_Model_name" NOT LIKE '%_ram_wifi_match';

    UPDATE "phone"
       SET "Accreditation_type" = "Accreditation_type" || '_dual_match'
     WHERE "chip_model" IN (
               SELECT cm."Model_name"
                 FROM "chip_model" cm
                WHERE cm."WiFi" = arg2
           )
       AND "screen_mode" IN (
               SELECT CAST(sm."Graphics_mode" AS text)
                 FROM "screen_mode" sm
                WHERE sm."Pixels" = arg4
                  AND sm."used_kb" = arg3
           )
       AND "Accreditation_type" NOT LIKE '%_dual_match';

    -- Post-handset sequence against current data
    UPDATE "chip_model"
       SET "WiFi" = arg2 || status_text
     WHERE "RAM_MiB" = arg1;

    result_val := result_val + 3;

    UPDATE "screen_mode"
       SET "Pixels" = arg4 || '_updated'
     WHERE "used_kb" = arg3;

    DELETE FROM "chip_model"
     WHERE "RAM_MiB" > result_val;

    status_text := 'active';

    UPDATE "screen_mode"
       SET "used_kb" = arg3 + 12
     WHERE "Pixels" = arg4;

    UPDATE "chip_model"
       SET "RAM_MiB" = result_val
     WHERE "WiFi" = arg2;

    result_val := result_val - 7;

    DELETE FROM "screen_mode"
     WHERE "Pixels" = arg4 || '_old';

    UPDATE "chip_model"
       SET "WiFi" = arg2 || '_final'
     WHERE "RAM_MiB" = arg1;

    status_text := 'completed';

    UPDATE "screen_mode"
       SET "used_kb" = arg3 * 3
     WHERE "Pixels" = arg4;

    DELETE FROM "chip_model"
     WHERE "WiFi" = arg2 || status_text;
END;
$$;

